//! Sum of 1..=n: read a u32 input, write the u64 result.
//!
//! Demonstrates the case-driven I/O syscalls. The host ships any number
//! of cases over `monolink upload --cases <file>`; the kernel relaunches
//! this program once per case with fresh `.data`/`.bss`, so `main`
//! reads exactly one input and writes exactly one output.
//!
//! Wire format (matches `.cases` files generated by hand or by the host):
//!   in:  4 bytes, u32 LE  — the value `n`
//!   out: 8 bytes, u64 LE  — the sum 1 + 2 + ... + n

#![no_std]
#![no_main]

fn main() {
    let mut buf = [0u8; 4];
    let n = userlib::read(&mut buf);
    if n < 4 {
        // Malformed input — exit with a sentinel the host can spot.
        userlib::exit(0xDEAD_BEEF);
    }
    let v = u32::from_le_bytes(buf);
    let sum: u64 = (1..=v as u64).sum();
    userlib::write(&sum.to_le_bytes());
}

userlib::entry!(main);
